What is the range of this graph?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.5]
\draw[gray!25,very thin] (-5,-5) grid (5,5);
\draw[->] (-5.3,0)--(5.3,0) node[right] {$x$};
\draw[->] (0,-5.3)--(0,5.3) node[above] {$y$};
\node[below,font=\scriptsize] at (-4,-0.12) {$-4$};
\node[below,font=\scriptsize] at (-2,-0.12) {$-2$};
\node[below,font=\scriptsize] at (2,-0.12) {$2$};
\node[below,font=\scriptsize] at (4,-0.12) {$4$};
\node[left,font=\scriptsize] at (-0.12,-4) {$-4$};
\node[left,font=\scriptsize] at (-0.12,-2) {$-2$};
\node[left,font=\scriptsize] at (-0.12,2) {$2$};
\node[left,font=\scriptsize] at (-0.12,4) {$4$};
\draw[thick] (-4,-1)--(2,5);
\fill[black] (-4,-1) circle (3pt);
\fill[black] (2,5) circle (3pt);
\end{tikzpicture}
[/tikz]

